# -*- coding: utf-8 -*-
"""
课件框架层 · 由 L22 源 HTML 提取固化（通用 CSS + 通用 JS + 页面组件 helper）。
解耦目标：L23+ 仅作为「内容层」调用本模块，不再运行时切块 L22，彻底消除跨课残留风险。
session 参数化：CORE_JS 内 L22_ 占位由 build_courseware(session=) 替换。
"""

CORE_CSS = "\n/* ==================== 全局变量与重置 ==================== */\n:root{\n  --brand:#E63946;--accent:#FFD700;--brand-light:#FF6B6B;--accent-light:#FFE66D;\n  --bg-start:#FFF8F0;--bg-end:#FFE8D6;--text-primary:#1A1A2E;--text-secondary:#555555;\n  --correct:#06A77D;--error:#E63946;--gray-node:#C0C0C0;--gray-border:#999999;\n  --card-bg:#FFFFFF;--table-header-bg:#E63946;--table-header-text:#FFFFFF;\n  --table-highlight-bg:#FFF8E1;--mnemonic-border:#FFD700;--mnemonic-text:#E63946;\n  --error-row-bg:#FFEBEE;--correct-row-bg:#E8F5E9;--page-shadow:0 4px 20px rgba(230,57,70,.15);\n  --card-shadow:0 2px 12px rgba(0,0,0,.08);\n  --sop-blue:#3B82F6;--sop-green:#10B981;--sop-purple:#8B5CF6;--sop-orange:#F59E0B;\n}\n*{margin:0;padding:0;box-sizing:border-box;}\nhtml,body{width:100%;height:100%;overflow:hidden;font-family:'Noto Sans SC','Microsoft YaHei','PingFang SC',sans-serif;\n  background:linear-gradient(135deg,var(--bg-start),var(--bg-end));color:var(--text-primary);}\nbutton{cursor:pointer;font-family:inherit;border:none;outline:none;background:none;}\ninput{font-family:inherit;outline:none;}\n\n/* ==================== 导航栏 ==================== */\n.nav-bar{position:fixed;top:0;left:0;width:100%;height:54px;background:rgba(255,255,255,.95);\n  backdrop-filter:blur(10px);box-shadow:0 2px 10px rgba(0,0,0,.1);z-index:1000;\n  display:flex;align-items:center;justify-content:center;gap:0;padding:0 20px;}\n.nav-item{display:flex;align-items:center;gap:6px;padding:8px 12px;font-size:14px;font-weight:500;\n  color:var(--text-secondary);cursor:pointer;transition:all .2s;border-radius:8px;white-space:nowrap;}\n.nav-item:hover{background:rgba(230,57,70,.08);color:var(--brand);}\n.nav-item.active{background:var(--brand);color:#fff;font-weight:600;}\n.nav-item .nav-num{font-size:13px;opacity:.7;}\n.nav-separator{width:16px;height:2px;background:var(--accent);border-radius:1px;opacity:.4;}\n\n/* ==================== 阶段徽章 ==================== */\n.stage-badge{position:fixed;top:10px;right:20px;z-index:1001;background:linear-gradient(135deg,var(--brand),var(--brand-light));\n  color:#fff;padding:6px 16px;border-radius:20px;font-size:14px;font-weight:600;box-shadow:0 2px 8px rgba(230,57,70,.3);\n  letter-spacing:.5px;}\n\n/* ==================== 数据同步状态 ==================== */\n.sync-status{position:fixed;top:10px;left:20px;z-index:1001;background:rgba(255,255,255,.9);\n  padding:4px 12px;border-radius:12px;font-size:12px;font-weight:600;color:var(--text-secondary);\n  box-shadow:0 2px 6px rgba(0,0,0,.08);display:flex;align-items:center;gap:6px;}\n.sync-dot{width:8px;height:8px;border-radius:50%;background:var(--correct);animation:pulse 2s infinite;}\n.sync-dot.pending{background:var(--sop-orange);}\n.sync-dot.failed{background:var(--error);}\n@keyframes pulse{0%,100%{opacity:1;}50%{opacity:.4;}}\n\n/* ==================== 页面容器 ==================== */\n.pages-container{position:absolute;top:54px;left:0;width:100%;height:calc(100% - 54px);overflow:hidden;aspect-ratio:21/9;}\n.page{position:absolute;top:0;left:0;width:100%;height:100%;display:none;overflow-y:auto;\n  padding:25px 45px 50px;background:linear-gradient(135deg,var(--bg-start),var(--bg-end));aspect-ratio:21/9;}\n.page.active{display:block;animation:pageFadeIn .4s ease-out;}\n@keyframes pageFadeIn{from{opacity:0;transform:translateX(30px);}to{opacity:1;transform:translateX(0);}}\n.page::-webkit-scrollbar{width:6px;}\n.page::-webkit-scrollbar-track{background:rgba(0,0,0,.05);}\n.page::-webkit-scrollbar-thumb{background:var(--brand-light);border-radius:3px;}\n\n/* ==================== 通用排版 ==================== */\n.page-title{font-size:36px;font-weight:700;color:var(--brand);margin-bottom:6px;text-align:center;\n  text-shadow:0 2px 4px rgba(230,57,70,.1);}\n.page-subtitle{font-size:20px;font-weight:400;color:var(--text-secondary);text-align:center;margin-bottom:18px;}\n.page-content{max-width:1500px;margin:0 auto;}\n.body-text{font-size:22px;line-height:1.6;color:var(--text-primary);}\n.highlight{color:var(--brand);font-weight:600;}\n.highlight-gold{color:#B8860B;font-weight:700;}\n.highlight-bold{font-weight:700;}\n.tag-review{display:inline-block;background:#e0e0e0;color:#666;padding:2px 10px;border-radius:10px;font-size:14px;font-weight:600;margin-left:8px;vertical-align:middle;}\n.tag-new{display:inline-block;background:var(--accent);color:#333;padding:2px 10px;border-radius:10px;font-size:14px;font-weight:700;margin-left:8px;vertical-align:middle;}\n.tag-sop{display:inline-block;background:var(--sop-blue);color:#fff;padding:2px 10px;border-radius:10px;font-size:14px;font-weight:600;margin-left:8px;}\n\n/* ==================== 统计面板 ==================== */\n.stats-panel{display:flex;gap:12px;justify-content:center;margin:12px 0;}\n.stats-card{background:#fff;border-radius:10px;padding:10px 20px;text-align:center;box-shadow:var(--card-shadow);min-width:110px;}\n.stats-card .stats-num{font-size:32px;font-weight:700;color:var(--brand);}\n.stats-card .stats-label{font-size:14px;color:var(--text-secondary);margin-top:2px;}\n.stats-card.gold .stats-num{color:#B8860B;}\n.stats-card.blue .stats-num{color:var(--sop-blue);}\n.stats-card.green .stats-num{color:var(--sop-green);}\n\n/* ==================== 表格样式 ==================== */\n.content-table{width:100%;border-collapse:collapse;margin:12px 0;font-size:18px;\n  box-shadow:var(--card-shadow);border-radius:10px;overflow:hidden;}\n.content-table thead{background:var(--table-header-bg);color:var(--table-header-text);}\n.content-table th{padding:10px 12px;font-size:18px;font-weight:600;text-align:center;}\n.content-table td{padding:8px 10px;text-align:center;border-bottom:1px solid #f0e0d0;font-size:17px;line-height:1.5;}\n.content-table tbody tr:nth-child(even){background:rgba(255,248,225,.5);}\n.content-table tbody tr:hover{background:var(--table-highlight-bg);}\n.content-table .hl-gold{background:rgba(255,215,0,.12);font-weight:600;}\n.content-table .hl-red{background:rgba(230,57,70,.08);font-weight:600;color:var(--brand);}\n.content-table .hl-blue{background:rgba(59,130,246,.08);font-weight:600;color:var(--sop-blue);}\n\n/* ==================== 词汇卡片 ==================== */\n.vocab-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:10px 0;}\n.vocab-card{background:#fff;border-radius:10px;padding:12px 16px;box-shadow:var(--card-shadow);\n  border-left:4px solid var(--brand);transition:all .2s;cursor:pointer;}\n.vocab-card:hover{transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,0,0,.12);}\n.vocab-card:nth-child(even){border-left-color:var(--accent);}\n.vocab-head{display:flex;align-items:center;gap:8px;margin-bottom:4px;}\n.vocab-word{font-size:22px;font-weight:700;color:var(--brand);}\n.vocab-card:nth-child(even) .vocab-word{color:#B8860B;}\n.vocab-phonetic{font-size:15px;color:var(--text-secondary);font-style:italic;}\n.vocab-pos{font-size:13px;background:var(--brand);color:#fff;padding:1px 8px;border-radius:8px;}\n.vocab-card:nth-child(even) .vocab-pos{background:var(--accent);color:#333;}\n.vocab-cn{font-size:18px;font-weight:600;color:var(--text-primary);margin-bottom:2px;}\n.vocab-collocation{font-size:14px;color:var(--text-secondary);margin-bottom:2px;}\n.vocab-example{font-size:14px;color:var(--text-primary);font-style:italic;line-height:1.4;}\n.vocab-memory{font-size:13px;color:var(--sop-purple);margin-top:2px;}\n\n/* ==================== 口诀卡片 ==================== */\n.mnemonic-card{background:linear-gradient(135deg,#FFFBF0,#FFF8E1);border:2px solid var(--mnemonic-border);\n  border-radius:14px;padding:16px 24px;margin:12px 0;box-shadow:0 4px 16px rgba(255,215,0,.2);\n  cursor:pointer;perspective:1000px;min-height:70px;}\n.mnemonic-card-inner{position:relative;width:100%;height:100%;transition:transform .5s;transform-style:preserve-3d;}\n.mnemonic-card.flipped .mnemonic-card-inner{transform:rotateY(180deg);}\n.mnemonic-front,.mnemonic-back{position:absolute;width:100%;backface-visibility:hidden;}\n.mnemonic-back{transform:rotateY(180deg);}\n.mnemonic-text{font-size:32px;font-weight:600;color:var(--mnemonic-text);line-height:1.6;text-align:center;font-style:italic;}\n.mnemonic-label{font-size:15px;color:var(--text-secondary);text-align:center;margin-bottom:6px;}\n.mnemonic-back .mnemonic-text{font-size:18px;color:var(--text-secondary);font-style:normal;text-align:left;line-height:1.6;}\n\n/* ==================== SOP流程图 ==================== */\n.sop-flowchart{display:flex;align-items:center;justify-content:center;gap:0;margin:16px 0;flex-wrap:wrap;}\n.sop-step{background:#fff;border-radius:12px;padding:16px 20px;text-align:center;box-shadow:var(--card-shadow);\n  min-width:140px;max-width:200px;border-top:4px solid var(--brand);position:relative;}\n.sop-step:nth-child(odd){border-top-color:var(--brand);}\n.sop-step:nth-child(even){border-top-color:var(--accent);}\n.sop-step-num{width:36px;height:36px;line-height:36px;text-align:center;background:var(--brand);color:#fff;\n  border-radius:50%;font-size:18px;font-weight:700;margin:0 auto 8px;}\n.sop-step:nth-child(even) .sop-step-num{background:var(--accent);color:#333;}\n.sop-step-title{font-size:18px;font-weight:700;color:var(--brand);margin-bottom:4px;}\n.sop-step:nth-child(even) .sop-step-title{color:#B8860B;}\n.sop-step-desc{font-size:14px;color:var(--text-secondary);line-height:1.4;}\n.sop-arrow{display:flex;align-items:center;color:var(--accent);font-size:28px;font-weight:700;padding:0 6px;}\n\n/* ==================== 答题区 ==================== */\n.quiz-question{background:#fff;border-radius:10px;padding:14px 18px;margin:10px 0;box-shadow:var(--card-shadow);}\n.quiz-q-text{font-size:19px;font-weight:600;margin-bottom:8px;color:var(--text-primary);}\n.quiz-q-text .q-num{display:inline-block;width:28px;height:28px;line-height:28px;text-align:center;background:var(--brand);color:#fff;border-radius:50%;font-size:14px;margin-right:8px;}\n.quiz-opts{display:flex;flex-direction:column;gap:6px;}\n.quiz-opt{padding:8px 14px;border:2px solid #ddd;border-radius:8px;font-size:17px;cursor:pointer;transition:all .2s;background:#fff;}\n.quiz-opt:hover{border-color:var(--brand-light);background:rgba(230,57,70,.03);}\n.quiz-opt.correct{border-color:var(--correct);background:var(--correct-row-bg);color:var(--correct);font-weight:600;}\n.quiz-opt.wrong{border-color:var(--error);background:var(--error-row-bg);color:var(--error);}\n.quiz-opt.disabled{pointer-events:none;opacity:.7;}\n.quiz-explain{display:none;margin-top:8px;padding:8px 12px;background:var(--table-highlight-bg);border-radius:6px;font-size:15px;color:var(--text-secondary);}\n.quiz-explain.show{display:block;animation:fadeIn .3s ease-out;}\n@keyframes fadeIn{from{opacity:0;}to{opacity:1;}}\n\n.fill-input{width:160px;padding:6px 12px;border:2px solid #ddd;border-radius:6px;font-size:18px;margin:0 6px;}\n.fill-input:focus{border-color:var(--brand);}\n.fill-input.correct{border-color:var(--correct);background:var(--correct-row-bg);}\n.fill-input.wrong{border-color:var(--error);background:var(--error-row-bg);}\n.fill-check-btn{padding:6px 16px;background:var(--accent);color:#333;border:none;border-radius:6px;font-size:16px;font-weight:600;cursor:pointer;margin-left:6px;}\n.fill-check-btn:hover{background:var(--accent-light);}\n.fill-answer{display:none;font-size:16px;color:var(--correct);font-weight:600;margin-top:4px;}\n.fill-answer.show{display:block;}\n\n/* 连线题 */\n.match-container{display:flex;gap:30px;justify-content:center;margin:14px 0;}\n.match-column{display:flex;flex-direction:column;gap:10px;min-width:260px;}\n.match-item{padding:10px 16px;background:#fff;border:2px solid #ddd;border-radius:8px;font-size:16px;cursor:pointer;transition:all .2s;text-align:center;}\n.match-item:hover{border-color:var(--brand-light);}\n.match-item.selected{border-color:var(--accent);background:rgba(255,215,0,.1);}\n.match-item.matched{border-color:var(--correct);background:var(--correct-row-bg);pointer-events:none;}\n.match-item.wrong-match{border-color:var(--error);background:var(--error-row-bg);animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-6px);}75%{transform:translateX(6px);}}\n\n/* 拖拽排序 */\n.drag-container{background:#fff;border-radius:10px;padding:14px;margin:10px 0;box-shadow:var(--card-shadow);}\n.drag-words{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px;min-height:50px;padding:8px;background:var(--table-highlight-bg);border-radius:8px;}\n.drag-word{padding:8px 16px;background:var(--brand);color:#fff;border-radius:8px;font-size:16px;cursor:grab;user-select:none;transition:all .15s;}\n.drag-word:hover{background:var(--brand-light);transform:translateY(-2px);}\n.drag-word.dragging{opacity:.5;}\n.drag-word.placed{background:var(--correct);}\n.drag-slot{display:inline-block;min-width:80px;height:38px;border:2px dashed #ccc;border-radius:6px;margin:0 4px;vertical-align:middle;}\n.drag-slot.filled{border-color:var(--correct);border-style:solid;}\n.drag-submit{padding:8px 20px;background:var(--accent);color:#333;border:none;border-radius:8px;font-size:17px;font-weight:600;cursor:pointer;margin-top:8px;}\n.drag-submit:hover{background:var(--accent-light);}\n.drag-result{margin-top:8px;font-size:17px;font-weight:600;}\n.drag-result.show{display:block;color:var(--brand);}\n.drag-word.selected{background:var(--accent);color:#333;transform:translateY(-3px);box-shadow:0 4px 12px rgba(255,215,0,.4);}\n.drag-word.used{opacity:.35;cursor:default;pointer-events:none;}\n.drag-slot.correct{border-color:var(--correct);border-style:solid;background:rgba(76,175,80,.1);}\n.drag-slot.wrong{border-color:var(--error);border-style:solid;background:rgba(244,67,54,.1);}\n\n/* 进度条 */\n.progress-bar{width:100%;height:8px;background:#e0e0e0;border-radius:4px;margin:10px 0;overflow:hidden;}\n.progress-bar-fill{height:100%;background:linear-gradient(90deg,var(--brand),var(--accent));border-radius:4px;transition:width .3s;width:0%;}\n.score-display{text-align:center;font-size:24px;font-weight:700;color:var(--brand);margin-top:10px;display:none;}\n.score-display.show{display:block;}\n\n/* ==================== 翻转卡 ==================== */\n.flip-card{perspective:1000px;height:130px;cursor:pointer;}\n.flip-card-inner{position:relative;width:100%;height:100%;transition:transform .6s;transform-style:preserve-3d;}\n.flip-card.flipped .flip-card-inner{transform:rotateY(180deg);}\n.flip-card-front,.flip-card-back{position:absolute;width:100%;height:100%;backface-visibility:hidden;\n  border-radius:10px;padding:12px 16px;display:flex;flex-direction:column;justify-content:center;box-shadow:var(--card-shadow);}\n.flip-card-front{background:#fff;border-left:4px solid var(--error);}\n.flip-card-back{background:var(--correct-row-bg);border-left:4px solid var(--correct);transform:rotateY(180deg);}\n.flip-card-front .flip-wrong{font-size:17px;color:var(--error);text-decoration:line-through;margin-bottom:4px;}\n.flip-card-front .flip-hint{font-size:14px;color:var(--text-secondary);}\n.flip-card-back .flip-right{font-size:17px;color:var(--correct);font-weight:600;margin-bottom:4px;}\n.flip-card-back .flip-explain{font-size:14px;color:var(--text-secondary);}\n\n/* ==================== 题型导图 ==================== */\n.exam-type-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0;}\n.exam-type-card{background:#fff;border-radius:12px;padding:14px;text-align:center;box-shadow:var(--card-shadow);\n  border-top:4px solid var(--brand);transition:all .2s;cursor:pointer;}\n.exam-type-card:hover{transform:translateY(-4px);box-shadow:0 6px 20px rgba(0,0,0,.12);}\n.exam-type-card:nth-child(1){border-top-color:var(--brand);}\n.exam-type-card:nth-child(2){border-top-color:var(--sop-blue);}\n.exam-type-card:nth-child(3){border-top-color:var(--sop-green);}\n.exam-type-card:nth-child(4){border-top-color:var(--sop-purple);}\n.exam-type-card:nth-child(5){border-top-color:var(--sop-orange);}\n.exam-type-icon{font-size:32px;margin-bottom:6px;}\n.exam-type-name{font-size:16px;font-weight:700;margin-bottom:4px;}\n.exam-type-score{font-size:24px;font-weight:700;color:var(--brand);}\n.exam-type-card:nth-child(2) .exam-type-score{color:var(--sop-blue);}\n.exam-type-card:nth-child(3) .exam-type-score{color:var(--sop-green);}\n.exam-type-card:nth-child(4) .exam-type-score{color:var(--sop-purple);}\n.exam-type-card:nth-child(5) .exam-type-score{color:var(--sop-orange);}\n.exam-type-focus{font-size:12px;color:var(--text-secondary);margin-top:4px;}\n\n/* ==================== 路线图 ==================== */\n.roadmap{display:flex;align-items:stretch;gap:0;margin:16px 0;}\n.roadmap-step{flex:1;background:#fff;border-radius:10px;padding:12px;text-align:center;\n  box-shadow:var(--card-shadow);position:relative;border-top:4px solid var(--brand);}\n.roadmap-step:nth-child(even){border-top-color:var(--accent);}\n.roadmap-step .step-num{font-size:26px;font-weight:700;color:var(--brand);}\n.roadmap-step .step-title{font-size:15px;font-weight:600;margin:4px 0;}\n.roadmap-step .step-time{font-size:12px;color:var(--text-secondary);}\n.roadmap-arrow{display:flex;align-items:center;color:var(--accent);font-size:22px;padding:0 4px;}\n\n/* ==================== 词性标注区 ==================== */\n.pos-sort-area{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin:14px 0;}\n.pos-box{background:#fff;border-radius:10px;padding:10px;min-height:120px;box-shadow:var(--card-shadow);border-top:4px solid;}\n.pos-box.noun{border-top-color:var(--brand);}\n.pos-box.verb{border-top-color:var(--sop-blue);}\n.pos-box.adj{border-top-color:var(--sop-green);}\n.pos-box.adv{border-top-color:var(--sop-purple);}\n.pos-box.pron{border-top-color:var(--sop-orange);}\n.pos-box-title{font-size:15px;font-weight:700;text-align:center;margin-bottom:8px;}\n.pos-box.noun .pos-box-title{color:var(--brand);}\n.pos-box.verb .pos-box-title{color:var(--sop-blue);}\n.pos-box.adj .pos-box-title{color:var(--sop-green);}\n.pos-box.adv .pos-box-title{color:var(--sop-purple);}\n.pos-box.pron .pos-box-title{color:var(--sop-orange);}\n.pos-word{display:inline-block;padding:4px 10px;margin:3px;border-radius:6px;font-size:14px;font-weight:600;cursor:grab;transition:all .15s;}\n.pos-word.noun{background:rgba(230,57,70,.1);color:var(--brand);}\n.pos-word.verb{background:rgba(59,130,246,.1);color:var(--sop-blue);}\n.pos-word.adj{background:rgba(16,185,129,.1);color:var(--sop-green);}\n.pos-word.adv{background:rgba(139,92,246,.1);color:var(--sop-purple);}\n.pos-word.pron{background:rgba(245,158,11,.1);color:var(--sop-orange);}\n.pos-word:hover{transform:scale(1.08);}\n.pos-word.placed{opacity:.3;pointer-events:none;}\n\n/* ==================== 封面 ==================== */\n.cover-container{text-align:center;padding:20px 0;}\n.cover-title{font-size:44px;font-weight:700;color:var(--brand);text-shadow:0 3px 6px rgba(230,57,70,.15);margin-bottom:10px;}\n.cover-subtitle{font-size:22px;color:var(--text-secondary);margin-bottom:20px;}\n.cover-info{display:flex;gap:16px;justify-content:center;margin-bottom:20px;flex-wrap:wrap;}\n.cover-info-item{background:#fff;padding:12px 26px;border-radius:12px;box-shadow:var(--card-shadow);border-top:3px solid var(--accent);text-align:center;}\n.cover-info-num{font-size:30px;font-weight:700;color:var(--brand);}\n.cover-info-label{font-size:13px;color:var(--text-secondary);}\n.cover-nav{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;}\n.cover-nav-item{display:flex;flex-direction:column;align-items:center;padding:10px 16px;background:#fff;\n  border-radius:10px;box-shadow:var(--card-shadow);cursor:pointer;transition:all .3s;min-width:90px;border-top:3px solid transparent;}\n.cover-nav-item:hover{transform:translateY(-5px);box-shadow:0 6px 16px rgba(0,0,0,.12);border-top-color:var(--brand);}\n.cover-nav-icon{font-size:26px;margin-bottom:4px;}\n.cover-nav-label{font-size:13px;font-weight:600;color:var(--text);}\n\n/* ==================== 阅读语篇 ==================== */\n.reading-passage{background:#fff;border-radius:10px;padding:18px 24px;margin:12px 0;box-shadow:var(--card-shadow);\n  font-size:19px;line-height:1.8;color:var(--text-primary);}\n.reading-passage .blank{display:inline-block;min-width:60px;border-bottom:2px solid var(--brand);text-align:center;\n  margin:0 4px;font-weight:700;color:var(--brand);}\n.reading-passage .blank.filled{color:var(--correct);border-color:var(--correct);}\n.reading-passage .blank.wrong{color:var(--error);border-color:var(--error);}\n\n/* ==================== 题号导航 ==================== */\n.q-nav{display:flex;gap:6px;justify-content:center;margin:10px 0;flex-wrap:wrap;}\n.q-nav-item{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;\n  font-size:14px;font-weight:700;cursor:pointer;transition:all .2s;background:#fff;border:2px solid #ddd;color:var(--text-secondary);}\n.q-nav-item:hover{border-color:var(--brand);color:var(--brand);}\n.q-nav-item.correct{background:var(--correct);color:#fff;border-color:var(--correct);}\n.q-nav-item.wrong{background:var(--error);color:#fff;border-color:var(--error);}\n.q-nav-item.current{background:var(--brand);color:#fff;border-color:var(--brand);transform:scale(1.15);}\n.q-nav-item.unanswered{background:#fff;color:var(--text-secondary);}\n\n/* ==================== 词汇游戏通用 ==================== */\n.vocab-game{background:linear-gradient(135deg,#FFFBF0,#FFF8E1);border:2px solid var(--accent);border-radius:14px;padding:18px;margin:10px 0;}\n.game-prompt{background:var(--brand);color:#fff;padding:8px 16px;border-radius:8px;font-size:16px;font-weight:600;margin-bottom:12px;text-align:center;}\n.game-option{padding:10px 16px;border:2px solid #ddd;border-radius:8px;font-size:17px;cursor:pointer;transition:all .2s;background:#fff;margin:4px 0;}\n.game-option:hover{border-color:var(--brand-light);background:rgba(230,57,70,.03);}\n.game-option.correct{border-color:var(--correct);background:var(--correct-row-bg);color:var(--correct);font-weight:600;}\n.game-option.wrong{border-color:var(--error);background:var(--error-row-bg);color:var(--error);}\n.game-feedback{margin-top:10px;padding:10px;border-radius:8px;font-size:16px;text-align:center;display:none;}\n.game-feedback.show{display:block;}\n.game-feedback.correct{background:var(--correct-row-bg);color:var(--correct);}\n.game-feedback.wrong{background:var(--error-row-bg);color:var(--error);}\n.game-progress{display:flex;gap:4px;justify-content:center;margin:8px 0;}\n.game-progress-dot{width:12px;height:12px;border-radius:50%;background:#ddd;transition:all .2s;}\n.game-progress-dot.correct{background:var(--correct);}\n.game-progress-dot.wrong{background:var(--error);}\n.game-progress-dot.current{background:var(--brand);transform:scale(1.3);}\n.context-box{background:#fff;border-left:4px solid var(--accent);border-radius:0 8px 8px 0;padding:10px 14px;margin:8px 0;font-size:18px;line-height:1.6;}\n.dialogue-line{padding:8px 14px;margin:4px 0;border-radius:8px;font-size:17px;line-height:1.5;}\n.dialogue-line.speaker-a{background:rgba(230,57,70,.06);border-left:3px solid var(--brand);}\n.dialogue-line.speaker-b{background:rgba(255,215,0,.1);border-left:3px solid var(--accent);margin-left:30px;}\n\n/* ==================== 自评卡片 ==================== */\n.eval-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0;}\n.eval-card{background:#fff;border-radius:10px;padding:14px;text-align:center;box-shadow:var(--card-shadow);cursor:pointer;transition:all .2s;border-top:4px solid;}\n.eval-card:nth-child(1){border-top-color:var(--correct);}\n.eval-card:nth-child(2){border-top-color:var(--accent);}\n.eval-card:nth-child(3){border-top-color:var(--brand);}\n.eval-card:nth-child(4){border-top-color:var(--error);}\n.eval-card:hover{transform:translateY(-3px);}\n.eval-grade{font-size:28px;font-weight:700;margin-bottom:4px;}\n.eval-card:nth-child(1) .eval-grade{color:var(--correct);}\n.eval-card:nth-child(2) .eval-grade{color:#B8860B;}\n.eval-card:nth-child(3) .eval-grade{color:var(--brand);}\n.eval-card:nth-child(4) .eval-grade{color:var(--error);}\n.eval-desc{font-size:13px;color:var(--text-secondary);line-height:1.5;}\n\n/* ==================== 完成徽章 ==================== */\n.completion-badge{display:flex;flex-direction:column;align-items:center;margin:16px 0;}\n.completion-circle{width:90px;height:90px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--accent-light));\n  display:flex;align-items:center;justify-content:center;font-size:36px;box-shadow:0 0 30px rgba(255,215,0,.5);\n  animation:badgeBounce .6s cubic-bezier(0.68,-0.55,0.265,1.55);}\n@keyframes badgeBounce{0%{transform:scale(0);opacity:0;}60%{transform:scale(1.2);opacity:1;}100%{transform:scale(1);opacity:1;}}\n.completion-text{font-size:20px;font-weight:700;color:var(--brand);margin-top:10px;}\n.completion-sub{font-size:15px;color:var(--text-secondary);margin-top:4px;}\n\n/* ==================== 知识图谱 ==================== */\n.graph-wrapper{position:relative;width:100%;height:480px;overflow:hidden;border-radius:12px;background:#fff;box-shadow:var(--card-shadow);}\n.graph-node{position:absolute;width:80px;height:80px;border-radius:50%;display:flex;align-items:center;justify-content:center;\n  font-size:13px;font-weight:700;text-align:center;cursor:pointer;transition:all .2s;border:3px solid;z-index:5;}\n.graph-node:hover{transform:scale(1.2);z-index:10;}\n.graph-center{width:110px;height:110px;background:radial-gradient(circle,var(--brand),var(--brand-light));color:#fff;border-color:var(--brand);\n  font-size:15px;box-shadow:0 0 20px rgba(230,57,70,.4);}\n.graph-line{position:absolute;z-index:1;pointer-events:none;}\n\n/* ==================== 防越级提醒 ==================== */\n.warning-box{background:rgba(230,57,70,.05);border:2px solid var(--brand);border-radius:10px;padding:10px 16px;margin:10px 0;}\n.warning-box .warning-title{font-size:17px;font-weight:700;color:var(--brand);margin-bottom:4px;}\n.warning-box .warning-text{font-size:16px;color:var(--text-primary);}\n\n/* ==================== 页码 ==================== */\n.page-counter{position:fixed;bottom:15px;right:20px;background:rgba(255,255,255,.9);padding:4px 14px;border-radius:15px;\n  font-size:15px;font-weight:600;color:var(--brand);z-index:1000;box-shadow:0 2px 8px rgba(0,0,0,.1);}\n\n/* ==================== 弹窗 ==================== */\n.modal-overlay{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.4);z-index:2000;\n  align-items:center;justify-content:center;}\n.modal-overlay.show{display:flex;}\n.modal-content{background:#fff;border-radius:16px;padding:24px 32px;max-width:500px;box-shadow:0 8px 40px rgba(0,0,0,.2);\n  text-align:center;animation:modalPop .3s ease-out;}\n@keyframes modalPop{from{transform:scale(.8);opacity:0;}to{transform:scale(1);opacity:1;}}\n.modal-title{font-size:22px;font-weight:700;color:var(--brand);margin-bottom:10px;}\n.modal-body{font-size:17px;color:var(--text-primary);line-height:1.6;}\n.modal-close{margin-top:14px;padding:8px 24px;background:var(--brand);color:#fff;border:none;border-radius:8px;font-size:15px;cursor:pointer;}\n\n/* ==================== 金色彩带 ==================== */\n.confetti-container{position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:3000;overflow:hidden;}\n.confetti-particle{position:absolute;width:10px;height:10px;background:var(--accent);border-radius:50%;\n  animation:confettiFall 1s ease-out forwards;}\n@keyframes confettiFall{from{transform:translate(0,0) scale(1);opacity:1;}to{transform:translate(var(--tx),var(--ty)) scale(0);opacity:0;}}\n\n/* ==================== 导出按钮 ==================== */\n.export-btn{position:fixed;top:56px;right:20px;background:var(--sop-blue);color:#fff;padding:6px 16px;\n  border-radius:15px;font-size:13px;font-weight:600;cursor:pointer;z-index:1000;box-shadow:0 2px 8px rgba(59,130,246,.3);\n  transition:all .2s;}\n.export-btn:hover{background:#2563EB;transform:translateY(-2px);}\n\n/* ==================== Mini Task ==================== */\n.mini-task-box{background:linear-gradient(135deg,#F0F9FF,#E0F2FE);border:2px solid var(--sop-blue);border-radius:14px;padding:18px;margin:12px 0;}\n.mini-task-header{display:flex;align-items:center;gap:8px;margin-bottom:10px;}\n.mini-task-icon{font-size:28px;}\n.mini-task-title{font-size:20px;font-weight:700;color:var(--sop-blue);}\n.mini-task-section{margin:8px 0;}\n.mini-task-label{font-size:15px;font-weight:700;color:var(--sop-blue);margin-bottom:4px;}\n.mini-task-content{font-size:16px;color:var(--text-primary);line-height:1.6;}\n.mini-task-words{display:flex;flex-wrap:wrap;gap:6px;margin-top:4px;}\n.mini-task-word-tag{background:rgba(59,130,246,.1);color:var(--sop-blue);padding:3px 10px;border-radius:8px;font-size:14px;font-weight:600;}\n\n/* ==================== 错因分析 ==================== */\n.error-analysis-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0;}\n.error-type-card{background:#fff;border-radius:10px;padding:14px;box-shadow:var(--card-shadow);cursor:pointer;transition:all .2s;\n  border-left:4px solid var(--error);perspective:1000px;min-height:100px;}\n.error-type-card:hover{transform:translateY(-3px);}\n.error-type-card.flipped{border-left-color:var(--correct);}\n.error-type-front{font-size:16px;font-weight:700;color:var(--error);}\n.error-type-back{display:none;font-size:14px;color:var(--correct);line-height:1.5;}\n.error-type-card.flipped .error-type-front{display:none;}\n.error-type-card.flipped .error-type-back{display:block;}\n\n"

CORE_JS = '/* ==================== Web Audio API ==================== */\nvar audioCtx = null;\nfunction initAudio(){\n  if(!audioCtx){\n    try{ audioCtx = new (window.AudioContext || window.webkitAudioContext)(); }catch(e){ console.log(\'Audio not supported\'); }\n  }\n  if(audioCtx && audioCtx.state === \'suspended\'){ audioCtx.resume(); }\n}\nfunction playCorrect(){\n  initAudio();\n  if(!audioCtx) return;\n  var freqs = [523.25, 659.25, 783.99];\n  freqs.forEach(function(f, i){\n    var osc = audioCtx.createOscillator();\n    var gain = audioCtx.createGain();\n    osc.type = \'triangle\';\n    osc.frequency.value = f;\n    gain.gain.setValueAtTime(0, audioCtx.currentTime + i * 0.12);\n    gain.gain.linearRampToValueAtTime(0.2, audioCtx.currentTime + i * 0.12 + 0.01);\n    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + i * 0.12 + 0.1);\n    osc.connect(gain);\n    gain.connect(audioCtx.destination);\n    osc.start(audioCtx.currentTime + i * 0.12);\n    osc.stop(audioCtx.currentTime + i * 0.12 + 0.1);\n  });\n}\nfunction playError(){\n  initAudio();\n  if(!audioCtx) return;\n  var freqs = [392.0, 261.63];\n  freqs.forEach(function(f, i){\n    var osc = audioCtx.createOscillator();\n    var gain = audioCtx.createGain();\n    osc.type = \'square\';\n    osc.frequency.value = f;\n    gain.gain.setValueAtTime(0, audioCtx.currentTime + i * 0.25);\n    gain.gain.linearRampToValueAtTime(0.15, audioCtx.currentTime + i * 0.25 + 0.01);\n    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + i * 0.25 + 0.2);\n    osc.connect(gain);\n    gain.connect(audioCtx.destination);\n    osc.start(audioCtx.currentTime + i * 0.25);\n    osc.stop(audioCtx.currentTime + i * 0.25 + 0.2);\n  });\n}\nfunction playPageTurn(){\n  initAudio();\n  if(!audioCtx) return;\n  var osc = audioCtx.createOscillator();\n  var gain = audioCtx.createGain();\n  osc.type = \'sine\';\n  osc.frequency.setValueAtTime(800, audioCtx.currentTime);\n  osc.frequency.exponentialRampToValueAtTime(400, audioCtx.currentTime + 0.08);\n  gain.gain.setValueAtTime(0.15, audioCtx.currentTime);\n  gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.08);\n  osc.connect(gain);\n  gain.connect(audioCtx.destination);\n  osc.start();\n  osc.stop(audioCtx.currentTime + 0.08);\n}\n\n\n/* ==================== IndexedDB 数据采集 ==================== */\nvar db = null;\nvar DB_NAME = \'EnglishCoursewareDB\';\nvar DB_VERSION = 1;\nvar STORE_NAME = \'answerRecords\';\nvar studentId = \'stu_xyj\';\nvar sessionId = \'L22_\' + new Date().toISOString().slice(0,10).replace(/-/g,\'\');\nvar answerRecords = [];\n\nfunction initDB(){\n  if(!window.indexedDB){ console.log(\'IndexedDB not supported\'); return; }\n  var request = indexedDB.open(DB_NAME, DB_VERSION);\n  request.onerror = function(e){ console.log(\'DB error:\', e); };\n  request.onsuccess = function(e){ db = e.target.result; loadExistingRecords(); };\n  request.onupgradeneeded = function(e){\n    db = e.target.result;\n    if(!db.objectStoreNames.contains(STORE_NAME)){\n      var store = db.createObjectStore(STORE_NAME, {keyPath: \'event_id\'});\n      store.createIndex(\'student_id\', \'student_id\', {unique: false});\n      store.createIndex(\'question_id\', \'question_id\', {unique: false});\n      store.createIndex(\'session_id\', \'session_id\', {unique: false});\n    }\n  };\n}\nfunction loadExistingRecords(){\n  if(!db) return;\n  var tx = db.transaction([STORE_NAME], \'readonly\');\n  var store = tx.objectStore(STORE_NAME);\n  var idx = store.index(\'session_id\');\n  var req = idx.getAll(sessionId);\n  req.onsuccess = function(e){\n    answerRecords = e.target.result || [];\n    updateSyncStatus();\n  };\n}\nfunction saveAnswer(questionId, studentAnswer, correctAnswer, isCorrect, attemptNo, timeUsed, hintUsed){\n  if(!db) return;\n  var event_id = studentId + \'_\' + sessionId + \'_\' + questionId + \'_\' + (attemptNo || 1);\n  var record = {\n    event_id: event_id,\n    student_id: studentId,\n    session_id: sessionId,\n    question_id: questionId,\n    attempt_no: attemptNo || 1,\n    student_answer: studentAnswer,\n    correct_answer: correctAnswer,\n    is_correct: isCorrect,\n    time_used: timeUsed || 0,\n    hint_used: hintUsed || false,\n    timestamp: new Date().toISOString(),\n    synced: \'pending\'\n  };\n  var tx = db.transaction([STORE_NAME], \'readwrite\');\n  var store = tx.objectStore(STORE_NAME);\n  store.put(record);\n  answerRecords.push(record);\n  updateSyncStatus();\n}\nfunction updateSyncStatus(){\n  var pending = answerRecords.filter(function(r){ return r.synced === \'pending\'; }).length;\n  var dot = document.getElementById(\'syncDot\');\n  var text = document.getElementById(\'syncText\');\n  if(!dot) return;\n  if(pending === 0){\n    dot.className = \'sync-dot\';\n    text.textContent = \'本地已保存 (\' + answerRecords.length + \'条)\';\n  } else {\n    dot.className = \'sync-dot pending\';\n    text.textContent = \'待同步 (\' + pending + \'/\' + answerRecords.length + \')\';\n  }\n}\nfunction exportData(e){\n  if(e) e.stopPropagation();\n  if(answerRecords.length === 0){\n    alert(\'暂无答题数据可导出\');\n    return;\n  }\n  var json = JSON.stringify(answerRecords, null, 2);\n  var csv = convertToCSV(answerRecords);\n  var jsonBlob = new Blob([json], {type: \'application/json\'});\n  var csvBlob = new Blob([\'\\uFEFF\' + csv], {type: \'text/csv\'});\n  var jsonLink = document.createElement(\'a\');\n  jsonLink.href = URL.createObjectURL(jsonBlob);\n  jsonLink.download = \'L22_answers.json\';\n  jsonLink.click();\n  setTimeout(function(){\n    var csvLink = document.createElement(\'a\');\n    csvLink.href = URL.createObjectURL(csvBlob);\n    csvLink.download = \'L22_answers.csv\';\n    csvLink.click();\n  }, 300);\n}\nfunction convertToCSV(records){\n  var headers = [\'event_id\',\'student_id\',\'session_id\',\'question_id\',\'attempt_no\',\'student_answer\',\'correct_answer\',\'is_correct\',\'time_used\',\'hint_used\',\'timestamp\'];\n  var csv = headers.join(\',\') + \'\\n\';\n  records.forEach(function(r){\n    var row = headers.map(function(h){\n      var val = r[h] !== undefined ? String(r[h]) : \'\';\n      if(val.indexOf(\',\') !== -1 || val.indexOf(\'"\') !== -1){ val = \'"\' + val.replace(/"/g, \'""\') + \'"\'; }\n      return val;\n    });\n    csv += row.join(\',\') + \'\\n\';\n  });\n  return csv;\n}\n\n\n/* ==================== 页面导航系统 ==================== */\nvar currentPage = 1;\nvar totalPages = 25;\nvar segmentPages = {1:[2,3], 2:[4,9], 3:[10,14], 4:[15,16], 5:[17,19], 6:[20,21], 7:[22,24], 8:[25,25]};\n\nfunction goToPage(pageNum){\n  if(pageNum < 1 || pageNum > totalPages) return;\n  initAudio();\n  var oldPage = document.getElementById(\'page\' + currentPage);\n  var newPage = document.getElementById(\'page\' + pageNum);\n  if(oldPage){ oldPage.classList.remove(\'active\'); oldPage.scrollTop = 0; }\n  if(newPage){ newPage.classList.add(\'active\'); newPage.scrollTop = 0; }\n  currentPage = pageNum;\n  updateNav();\n  updateCounter();\n  playPageTurn();\n}\nfunction nextPage(){ if(currentPage < totalPages) goToPage(currentPage + 1); }\nfunction prevPage(){ if(currentPage > 1) goToPage(currentPage - 1); }\nfunction jumpToSegment(seg){\n  var pages = segmentPages[seg];\n  if(pages) goToPage(pages[0]);\n}\nfunction updateNav(){\n  var items = document.querySelectorAll(\'.nav-item\');\n  items.forEach(function(item){\n    var seg = parseInt(item.dataset.segment);\n    var pages = segmentPages[seg];\n    if(currentPage >= pages[0] && currentPage <= pages[1]){\n      item.classList.add(\'active\');\n    } else {\n      item.classList.remove(\'active\');\n    }\n  });\n}\nfunction updateCounter(){\n  document.getElementById(\'pageCounter\').textContent = currentPage + \' / \' + totalPages;\n}\n\n\n/* ==================== 翻页区域 ==================== */\ndocument.addEventListener(\'click\', function(e){\n  if(e.target.closest(\'.quiz-opt\') || e.target.closest(\'.game-option\') ||\n     e.target.closest(\'.fill-check-btn\') || e.target.closest(\'.fill-input\') ||\n     e.target.closest(\'.nav-item\') || e.target.closest(\'.vocab-card\') ||\n     e.target.closest(\'.flip-card\') || e.target.closest(\'.mnemonic-card\') ||\n     e.target.closest(\'.error-type-card\') || e.target.closest(\'.exam-type-card\') ||\n     e.target.closest(\'.eval-card\') || e.target.closest(\'.cover-nav-item\') ||\n     e.target.closest(\'.modal-content\') || e.target.closest(\'.export-btn\') ||\n     e.target.closest(\'.drag-word\') || e.target.closest(\'.drag-submit\') ||\n     e.target.closest(\'.drag-container\') || e.target.closest(\'.link-container\') ||\n     e.target.closest(\'.order-container\') ||\n     e.target.closest(\'.match-item\') || e.target.closest(\'.pos-word\') ||\n     e.target.closest(\'button\') || e.target.closest(\'input\') ||\n     e.target.closest(\'.game-progress-dot\') || e.target.closest(\'.q-nav-item\')){\n    return;\n  }\n  var container = document.getElementById(\'pagesContainer\');\n  var rect = container.getBoundingClientRect();\n  var x = e.clientX - rect.left;\n  if(x < rect.width / 2){ prevPage(); }\n  else { nextPage(); }\n});\n\n\n/* ==================== 键盘导航 ==================== */\ndocument.addEventListener(\'keydown\', function(e){\n  if(e.target.tagName === \'INPUT\') return;\n  if(e.key === \'ArrowLeft\' || e.key === \'ArrowUp\'){ prevPage(); }\n  else if(e.key === \'ArrowRight\' || e.key === \'ArrowDown\' || e.key === \' \'){ e.preventDefault(); nextPage(); }\n  else if(e.key === \'f\' || e.key === \'F\'){\n    if(!document.fullscreenElement){ document.documentElement.requestFullscreen(); }\n    else { document.exitFullscreen(); }\n  }\n});\n\n\n/* ==================== 弹窗 ==================== */\nfunction closeModal(e){\n  if(e && e.target !== document.getElementById(\'modalOverlay\')) return;\n  document.getElementById(\'modalOverlay\').classList.remove(\'show\');\n}\n\n'


# ==================== 框架层 helper ====================
def page(pid, title, subtitle, inner, active=False):
    cls = "page active" if active else "page"
    return ('<div class="%s" id="page%d">\n  <div class="page-content">\n    <h1 class="page-title">%s</h1>\n'
            '    <p class="page-subtitle">%s</p>\n%s\n  </div>\n</div>\n' % (cls, pid, title, subtitle, inner))

def vocab_cards(vs):
    out = []
    for en, ph, pos, cn, coll, ex, mem in vs:
        out.append(
            '<div class="vocab-card" onclick="event.stopPropagation()">'
            '<div class="vocab-head"><span class="vocab-word">%s</span><span class="vocab-phonetic">%s</span>'
            '<span class="vocab-pos">%s</span></div>'
            '<div class="vocab-cn">%s</div>'
            '<div class="vocab-collocation">搭配：%s</div>'
            '<div class="vocab-example">%s</div>'
            '<div class="vocab-memory">记忆：%s</div></div>'
            % (en, ph, pos, cn, coll, ex, mem))
    return '<div class="vocab-grid">' + "\n".join(out) + "</div>"

