def build_courseware(title, pages_dict, js_extra, session="L23",
                     nav_html=DEFAULT_NAV, stage_badge="Stage 5 · L23 刷题冲刺", n_pages=None, css_extra=None):
    """组装单文件课件 HTML。session 用于替换框架内 L22_ 占位与答题数据文件名。"""
    js = CORE_JS.replace("L22_", session + "_").replace("L22_answers", session + "_answers")
    badge_html = '<div class="stage-badge">%s</div>' % stage_badge
    sync_html = '<div class="sync-status"><div class="sync-dot" id="syncDot"></div><span id="syncText">本地已保存</span></div>'
    export_html = '<div class="export-btn" onclick="exportData(event)">导出答题数据</div>'
    if n_pages is None:
        n_pages = max(pages_dict.keys())
    pages_html = "\n".join(pages_dict[i] for i in range(1, n_pages + 1))
    html = (
        '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="UTF-8">\n'
        '<meta name="viewport" content="width=device-width, initial-scale=1.0">\n'
        '<title>' + title + '</title>\n<style>\n' + CORE_CSS + '\n' + (css_extra or "") + '\n</style>\n</head>\n<body>\n'
        + nav_html + '\n' + badge_html + '\n' + sync_html + '\n' + export_html + '\n'
        '<div class="pages-container" id="pagesContainer">\n' + pages_html + '\n</div>\n'
        '<div class="page-counter" id="pageCounter">1 / ' + str(n_pages) + '</div>\n'
        '<div class="modal-overlay" id="modalOverlay" onclick="closeModal(event)"><div class="modal-content" id="modalContent"></div></div>\n'
        '<script>\n' + js + '\n' + js_extra + '\n</script>\n</body>\n</html>'
    )
    return html
